E = {}
def e(n, k):
    if n <= 1:
        return F(0)
    if (n, k) in E:
        return E[(n, k)]
    tot = F(0)
    for i in range(1, n + 1):
        if i == k:
            pass
        elif i > k:
            tot += e(i - 1, k)
        else:
            tot += e(n - i, k - i)
    E[(n, k)] = (n - 1) + tot / n
    return E[(n, k)]
